param([string]$Python="python",[string]$OutputJson="",[switch]$RequireDevTools)
$ErrorActionPreference='Stop';$r=@();function A($n,$ok,$d,$req=$true){$script:r+=[pscustomobject]@{name=$n;ok=[bool]$ok;required=[bool]$req;detail=$d};Write-Host "[$(if($ok){'PASS'}elseif($req){'FAIL'}else{'WARN'})] $n - $d"};$win=$env:OS-eq'Windows_NT';A 'Windows host' $win $env:OS $true;if(-not$win){exit 2};$os=Get-CimInstance Win32_OperatingSystem;$build=[int]$os.BuildNumber;A 'Windows 11 generation' ($build-ge22000) "$($os.Caption) build $build";$py=Get-Command $Python -ErrorAction SilentlyContinue;A 'Python' ([bool]$py) $(if($py){$py.Source}else{'not found'});$wv=@((Join-Path ${env:ProgramFiles(x86)} 'Microsoft\EdgeWebView\Application'),(Join-Path $env:ProgramFiles 'Microsoft\EdgeWebView\Application'),(Join-Path $env:LOCALAPPDATA 'Microsoft\EdgeWebView\Application'))|?{$_ -and(Test-Path $_)};A 'WebView2 Runtime' ($wv.Count-gt0) $(if($wv){$wv-join'; '}else{'not found'});foreach($x in @('git','node','cargo')){$c=Get-Command $x -ErrorAction SilentlyContinue;A $x ([bool]$c) $(if($c){$c.Source}else{'not found'}) $RequireDevTools};$failed=@($r|?{$_.required-and-not$_.ok});$o=@{schema=1;ready=$failed.Count-eq0;os=@{caption=$os.Caption;build=$build};checks=$r};if($OutputJson){$o|ConvertTo-Json -Depth 6|Set-Content -Encoding UTF8 $OutputJson};if($failed.Count){exit 2}
